-- 045_skancode_logo_fordel.sql
-- SkanCode (mail 7. okt. 2026): nyt blåt logo i stedet for det røde, og deres egen tekst
-- til fordelen for SmartPack-kunder.
UPDATE partner
   SET logo = decode('', 'base64'),
       logo_type = 'image/png',
       fordel_rabat = 'Specialpriser til SmartPack-kunder!',
       fordel_ydelse = 'Den rette hardware til SmartPack – uden bøvl. Hos SkanCode er vi specialister i stregkodehardware: håndterminaler, håndscannere og labelprintere. Gennem vores tætte samarbejde med SmartPack hjælper vi dig med at vælge det udstyr, der passer til både lageret og SmartPacks WMS.',
       fordel_koebskrav = E'Vi kender de nødvendige indstillinger og hjælper med opsætning og support, så du kommer godt i gang og får udstyret til at spille sammen. Som SmartPack-kunde får du desuden specialpriser på udvalgte produkter.\n\nTag fat i SkanCode – så finder vi det rette udstyr til dig.',
       opdateret = now()
 WHERE lower(navn) = 'skancode';
